tool_input.command:
cat >> test/cli.test.js <<'EOF'

test('words: a run of spaces, tabs and newlines is a single separator', () => {
  assert.deepEqual(run(['words', fileContaining('one   two\t\tthree\n\nfour \t\n five')]), {
    code: 0,
    out: 'words: 5',
  })
})
EOF
node --test test/cli.test.js 2>&1 | grep -E "^(✔|✖)|out: 'words" | head

cat >> test/cli.test.js <<'EOF'

test('lines: a last line without a trailing newline still counts', () => {
  assert.deepEqual(run(['lines', fileContaining('a\nb')]), { code: 0, out: 'lines: 2' })
})
EOF
npm test 2>&1 | grep -E '^(not ok|# (pass|fail))'

cat >> src/counts.js <<'EOF'

/**
 * The number of characters in `text`.
 * @param {string} text
 * @returns {number}
 */
export function countCharacters(text) {
  return text.length
}
EOF
cat src/counts.js

cat >> test/cli.test.js <<'EOF'

test('characters: a line ending counts as characters, so \\r\\n is two', () => {
  assert.deepEqual(run(['characters', fileContaining('\r\n')]), { code: 0, out: 'characters: 2' })
})
EOF
npm test 2>&1 | grep -E '^ℹ (tests|pass|fail)|^✖'
cat >> test/cli.test.js <<'EOF'

test('characters: an empty file has no characters', () => {
  assert.deepEqual(run(['characters', fileContaining('')]), { code: 0, out: 'characters: 0' })
})
EOF
npm test 2>&1 | grep -E '^ℹ (tests|pass|fail)|^✖'

cat >> test/cli.test.js <<'EOF'

test('all: one report with words, lines and characters, in that order', () => {
  // precomposed é (U+00E9); 👋 is one code point but two UTF-16 units
  assert.deepEqual(run(['all', fileContaining('héllo 👋\nsecond line\n')]), {
    code: 0,
    out: 'words: 4\nlines: 2\ncharacters: 20',
  })
})
EOF
npm test 2>&1 | grep -E '^(✖|ℹ (pass|fail))|actual|expected|\+|-' | head -20

cat >> test/cli.test.js <<'EOF'

test('all: an empty file reports zero for every count', () => {
  assert.deepEqual(run(['all', fileContaining('')]), {
    code: 0,
    out: 'words: 0\nlines: 0\ncharacters: 0',
  })
})
EOF
npm test 2>&1 | grep -E '^(✖|ℹ (tests|pass|fail))|^\s+[+-] '

